dashboard.kpi.unpaid_detail:
.input {$count :number}
.match $count
one {{{$count} invoice to collect}}
* {{{$count} invoices to collect}}

emp.absence_requested:
.input {$n :number}
.match $n
one {{Absence requested: {$n} business day}}
* {{Absence requested: {$n} business days}}

imports.error_rows:
.input {$count :number}
.match $count
one {{{$count} row in error, not imported:}}
* {{{$count} rows in error, not imported:}}

quote.parties_valid:
.input {$days :number}
.match $days
one {{From {$issuer} for {$client}, issued on {$date}, valid for {$days} day.}}
* {{From {$issuer} for {$client}, issued on {$date}, valid for {$days} days.}}
